  void Awake(){Instance=this;try{string isolated=Environment.GetEnvironmentVariable("INFSTUDIO_CONFIG_ROOT");string root=string.IsNullOrWhiteSpace(isolated)?Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"infstudio"):isolated;cacheRoot=root;bool legacy=File.Exists(Path.Combine(root,"spectrogram.cfg"));var prefs=new ConfigFile(Path.Combine(root,"spectrogram.cfg"),false);Enabled=prefs.Bind("Spectrogram","Enabled",false,"Independent central-lane spectrogram, including the gaps. Does not control the waveform.");HidePlaying=prefs.Bind("Spectrogram","HideDuringPlayback",false,"Hide during playback, preview, gameplay and video export.");Mirror=prefs.Bind("Spectrogram","Mirror",false,"Reverse only the horizontal frequency axis.");Opacity=prefs.Bind("Spectrogram","Opacity",128,new ConfigDescription("Opacity from 0 to 255.",new AcceptableValueRange<int>(0,255)));Samples=prefs.Bind("Spectrogram","FftSamples",SpectrumMath.Bins,new ConfigDescription("Number of output frequency columns; analysis windows remain independently optimized.",new AcceptableValueRange<int>(2,2048)));Samples.Value=SpectrumMath.ValidBins(Samples.Value);WindowMs=prefs.Bind("Spectrogram","AnalysisWindowMs",legacy?0d:20d,"Independent analysis time in ms; zero migrates the previous effective window once audio loads.");bundlePath=Path.Combine(Path.GetDirectoryName(GetType().Assembly.Location),"spectrogram.bundle");harmony=new Harmony("local.infalsusstudio.spectrogram.ui");harmony.Patch(StudioBridge.Method("MatchedWave"),postfix:new HarmonyMethod(GetType().GetMethod("DrawSettings",StudioBridge.F)));harmony.Patch(StudioBridge.Method("MatchedContentHeight"),postfix:new HarmonyMethod(GetType().GetMethod("PanelHeight",StudioBridge.F)));RenderPipelineManager.beginCameraRendering+=BeginCamera;RenderPipelineManager.endCameraRendering+=EndCamera;Logger.LogInfo("Independent spectrogram ready; original stage and waveform retained.");}catch(Exception e){Failure=e.Message;Logger.LogError(e