  void BeginCamera(ScriptableRenderContext context,Camera camera){if(Failure!=null||Enabled==null)return;try{var boot=StudioBridge.Boot;if(!boot||camera!=boot.ViewCamera)return;if(!Visible(Enabled.Value,HidePlaying.Value,StudioBridge.Playing(boot),Opacity.Value)||Analysis==null||Analysis.Clip!=StudioBridge.Transport(boot).Clip||Analysis.Bins!=Samples.Value){if(Renderer!=null)Renderer.Hide();return;}if(Renderer==null){int layer;var parent=StudioBridge.StageParent(boot,out layer);Renderer=new SpectrumRenderer(bundlePath,parent,layer);}Renderer.Draw(Analysis,StudioBridge.Now(boot),StudioBridge.Transport(boot).AudioOffsetMs,boot.Profile,Opacity.Value,Mirror.Value);DrawCalls++;}catch(Exception e){Fail(e);}}
  void EndCamera(ScriptableRenderContext context,Camera camera){if(Renderer!=null&&owner&&camera==owner.ViewCamera)Renderer.Hide();}
  void Fail(Exception e){Failure=e.Message;Logger.LogError("Spectrogram disabled independently: "+e);Release();}
  internal void Release(){if(Analysis!=null){var disk=Analysis.Disk;Analysis.Dispose();System.Threading.Tasks.Task.Run(()=>disk.Prune());}Analysis=null;if(Renderer!=null)Renderer.Dispose();Renderer=null;owner=null;}
